import csv
from typing import Generator, Dict, Any, Optional, Union, List, Set

class CSVFileNotFoundError(Exception):
    pass

class CSVStructureError(Exception):
    pass

class CSVRowError(Exception):
    pass

def convert_value(value: str) -> Optional[Any]:
    """
    Convert string value to int, float, or None if empty.
    """
    if value.strip() == '':
        return None
    try:
        return int(value)
    except ValueError:
        try:
            return float(value)
        except ValueError:
            return value.strip()

def parse_csv_stream(
    filename: str,
    columns: Union[List[str], Set[str], None] = None
) -> Generator[Dict[str, Optional[Any]], None, None]:
    """
    Stream a CSV file into a sequence of dictionaries, one row at a time, with optional column filtering.

    Args:
        filename (str): Path to the CSV file.
        columns (List[str], Set[str], or None): Names of the columns to include. 
            If None, all columns are returned.

    Yields:
        Dict[str, Optional[Any]]: A dictionary with only the selected columns.

    Raises:
        CSVFileNotFoundError: If the file is not found.
        CSVStructureError: If the CSV is malformed (e.g., inconsistent columns).
        CSVRowError: If there's a general error processing a row.
    """
    try:
        with open(filename, newline='', encoding='utf-8') as csvfile:
            reader = csv.DictReader(csvfile)
            fieldnames = reader.fieldnames

            if not fieldnames:
                raise CSVStructureError("CSV file has no headers.")

            if columns:
                # Convert to set for faster lookups
                selected_columns = set(columns)
                # Check if all requested columns exist
                for col in selected_columns:
                    if col not in fieldnames:
                        raise CSVStructureError(f"Requested column '{col}' not found in CSV headers.")
                expected_keys = selected_columns
            else:
                expected_keys = set(fieldnames)

            for idx, row in enumerate(reader, start=1):
                if set(row.keys()) != set(fieldnames):
                    raise CSVStructureError(f"Row {idx} has inconsistent columns.")
                if columns:
                    filtered_row = {k: convert_value(v) for k, v in row.items() if k in selected_columns}
                else:
                    filtered_row = {k: convert_value(v) for k, v in row.items()}
                yield filtered_row

    except FileNotFoundError:
        raise CSVFileNotFoundError(f"CSV file not found: {filename}")
    except csv.Error as e:
        raise CSVStructureError(f"Malformed CSV: {e}")
    except Exception as e:
        raise CSVRowError(f"Error processing CSV: {e}")
